package com.exe201.rrms.repository; import com.exe201.rrms.entity.Follow; import org.springframework.data.jpa.repository.JpaRepository; import java.util.*; public interface FollowRepository extends JpaRepository<Follow,Long>{ Optional<Follow> findByFollowerIdAndFollowingId(Long followerId,Long followingId); long countByFollowingId(Long followingId); long countByFollowerId(Long followerId); List<Follow> findByFollowerId(Long followerId); }